// Map phone numbers / sender contacts to sites & supervisors
const payload = $input.item.json;

// Phone number directory (Customize phone numbers to match your supervisors)
const supervisorDirectory = {
  "254700000001": { name: "Ken / Mr. Gichuhi", site: "Mucheru World of Golf", siteKey: "mucheruGolf" },
  "254700000002": { name: "Willy / Kamandau", site: "Chaka Farms", siteKey: "chakaFarms" },
  "254700000003": { name: "Njoki", site: "Kabete Residence", siteKey: "kabeteResidence" },
  "254700000004": { name: "Edwin", site: "Amani Cottage", siteKey: "amaniCottage" }
};

// Extract message details (Supports WAHA / standard webhook formats)
const sender = (payload.from || payload.sender || payload.phone || "").replace(/[^0-9]/g, "");
const text = payload.text || payload.body || payload.caption || "";
const hasMedia = Boolean(payload.mediaUrl || payload.hasMedia || payload.fileUrl);
const mediaUrl = payload.mediaUrl || payload.fileUrl || "";
const mediaType = payload.mimetype || payload.mediaType || "";

const supervisorInfo = supervisorDirectory[sender] || {
  name: payload.senderName || "Unknown Supervisor",
  site: "Unclassified Site",
  siteKey: "unclassified"
};

// Generate today's folder name (e.g., Report 27th Aug)
const now = new Date();
const day = now.getDate();
const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const month = monthNames[now.getMonth()];
const suffix = (day === 1 || day === 21 || day === 31) ? 'st' :
               (day === 2 || day === 22) ? 'nd' :
               (day === 3 || day === 23) ? 'rd' : 'th';
const folderName = `Report ${day}${suffix} ${month}`;
const baseFolder = `C:\\Users\\denni\\Downloads\\Reporting\\${folderName}`;

return [
  {
    json: {
      timestamp: now.toISOString(),
      sender,
      supervisor: supervisorInfo.name,
      site: supervisorInfo.site,
      siteKey: supervisorInfo.siteKey,
      text,
      hasMedia,
      mediaUrl,
      mediaType,
      targetFolder: baseFolder
    }
  }
];
